const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const northKenya = ee.Geometry.Polygon([[
        [36.5, 2.5], [40.0, 2.5], [40.0, 4.5], [36.5, 4.5]
    ]]);
    const southKenya = ee.Geometry.Polygon([[
        [36.5, -3.5], [40.0, -3.5], [40.0, -1.5], [36.5, -1.5]
    ]]);
    const dateRange = ee.DateRange('2019-05-01', '2019-06-30');

    // 2. Data Acquisition & Processing Functions
    const S2_SR_COLLECTION = 'COPERNICUS/S2_SR_HARMONIZED';

    function maskS2clouds(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                     qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
            .select("B.*")
            .copyProperties(image, ["system:time_start"]);
    }

    function addNDVI(image) {
        const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
        return image.addBands(ndvi);
    }

    // 3. Image Collection Retrieval and Processing
    const baseCollection = ee.ImageCollection(S2_SR_COLLECTION)
        .filterDate(dateRange)
        .filter(ee.Filter.or(
            ee.Filter.bounds(northKenya),
            ee.Filter.bounds(southKenya)
        ));

    const collectionSize = baseCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log("No images found for the specified date range and locations.");
        console.log("C1");
        return;
    }

    const processedCollection = baseCollection.map(maskS2clouds).map(addNDVI);

    // 4. Regional NDVI Calculation
    const getRegionMean = function(geometry) {
        const image = processedCollection.filterBounds(geometry).mean().select('NDVI');

        const stats = image.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: geometry,
            scale: 3000,
            maxPixels: 1e9
        });
        return stats;
    };

    const northStats = getRegionMean(northKenya).getInfo();
    const southStats = getRegionMean(southKenya).getInfo();

    const northNDVI = northStats.NDVI_mean;
    const northPixels = northStats.NDVI_count;
    const southNDVI = southStats.NDVI_mean;
    const southPixels = southStats.NDVI_count;

    // 5. Validation & Final Answer
    console.log(`Image collection size: ${collectionSize}`);
    console.log(`Northern Kenya Valid Pixels: ${northPixels}`);
    console.log(`Southern Kenya Valid Pixels: ${southPixels}`);

    if (northPixels === 0 || southPixels === 0) {
        console.log("No valid pixels found after cloud masking in one or both regions.");
        console.log("C2");
        return;
    }

    if (northNDVI === null || southNDVI === null || isNaN(northNDVI) || isNaN(southNDVI)) {
        console.log("Failed to calculate a valid NDVI value.");
        console.log("C3");
        return;
    }

    console.log(`Northern Kenya Mean NDVI: ${northNDVI.toFixed(4)}`);
    console.log(`Southern Kenya Mean NDVI: ${southNDVI.toFixed(4)}`);

    if (northNDVI < southNDVI) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error: ${e.toString()}`);
    console.log("D");
  }
}

initEE();
